3	import { useState, useTransition } from "react";
4	import { useRouter } from "next/navigation";
5	import { deleteLead, updateLeadStatus } from "@/app/actions";
6	import { LEAD_STATUSES, type LeadStatus } from "@/lib/types";
7	import { STATUS_LABELS } from "./status-badge";
8	
9	export function LeadActions({ leadId, status }: { leadId: string; status: LeadStatus }) {
10	  const router = useRouter();
11	  const [current, setCurrent] = useState<LeadStatus>(status);
12	  const [pending, startTransition] = useTransition();
13	
14	  function changeStatus(next: LeadStatus) {
15	    setCurrent(next);
16	    startTransition(async () => {
17	      await updateLeadStatus(leadId, next);
18	      router.refresh();
19	    });
20	  }
21	
22	  function remove() {
23	    if (!window.confirm("Видалити лід назавжди?")) return;
24	    startTransition(async () => {
25	      await deleteLead(leadId);
26	      router.push("/dashboard");
27	    });
28	  }
29	
30	  return (
31	    <div className="flex flex-wrap items-end justify-between gap-4 rounded-lg border border-slate-200 bg-white p-5">
32	      <label className="text-sm font-medium">
33	        Статус
34	        <select
35	          value={current}
36	          disabled={pending}
37	          onChange={(event) => changeStatus(event.target.value as LeadStatus)}
38	          className="mt-1 block rounded-md border border-slate-300 px-3 py-2 text-sm"
39	        >
40	          {LEAD_STATUSES.map((value) => (
41	            <option key={value} value={value}>
42	              {STATUS_LABELS[value]}
43	            </option>
44	          ))}
45	        </select>
46	      </label>
47	      <button
48	        type="button"
