    return { status: "invalid", errors: parsed.errors };
  }

  const requestHeaders = await headers();
  const ipAddress = requestHeaders.get("x-forwarded-for")?.split(",")[0].trim() ?? "127.0.0.1";
  const userAgent = requestHeaders.get("user-agent") ?? "";

  const lead = await db.insertLead({
    ...parsed.data,
    workspaceId: PUBLIC_FORM_WORKSPACE_ID,
    jobTitle: "",
    city: "",
    country: "",
    source: "website",
    utmSource: null,
    utmMedium: null,
    utmCampaign: null,
    ipAddress,
    userAgent,
    rawPayload: {
      form: { id: "contact-main", version: "2026-07", fields: parsed.data },
      request: {
        ip: ipAddress,
        userAgent,
        acceptLanguage: requestHeaders.get("accept-language"),
        receivedAt: new Date().toISOString(),
      },
    },
  });

  try {
    await fetch(process.env.N8N_WEBHOOK_URL!, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(lead),
    });
  } catch (error) {
    console.error(`Failed to send lead ${lead.id} to n8n`, error);
  }

  await logAudit("lead.created", lead.id);

  return { status: "ok" };
}

// Server Actions are public POST endpoints: check the session and the lead's workspace inside
// each action, not only in proxy.ts or the page (rule server-auth-actions).
async function authorizeLead(id: unknown) {
  const user = await getCurrentUser(); // no session -> redirect("/login")
  if (typeof id !== "string") throw new Error("Lead not found");
  const [workspace, lead] = await Promise.all([getWorkspace(user.workspaceSlug), db.getLead(id)]);
  if (!lead || lead.workspaceId !== workspace.id) throw new Error("Lead not found");
  return lead.id;
}

export async function updateLeadStatus(id: string, status: LeadStatus) {
  if (!LEAD_STATUSES.includes(status)) throw new Error("Unknown status");
  await authorizeLead(id);
  await db.updateLeadStatus(id, status);
  revalidatePath("/dashboard");
  revalidatePath(`/dashboard/leads/${id}`);
}

export type AddLeadNoteState =
  | { status: "idle" }
  | {
      status: "invalid";
      errors: Partial<Record<LeadNoteField, string>>;
      values: Partial<Record<LeadNoteField, string>>;
    }
  | { status: "ok" }
  | { status: "error" };

// Bound as addLeadNote.bind(null, leadId): the id is still client-controlled, so check it here.
export async function addLeadNote(
  id: string,
  _prevState: AddLeadNoteState,
  formData: FormData,
): Promise<AddLeadNoteState> {
  await getCurrentUser(); // no session -> redirect("/login"); outside the catch below
  const leadId = await authorizeLead(id).catch(() => null);
  if (!leadId) return { status: "error" };

  const parsed = parseLeadNoteForm(formData);
  if (!parsed.ok) {
    return { status: "invalid", errors: parsed.errors, values: parsed.values };
  }

  const saved = await db.appendLeadNote(leadId, parsed.data.note);
  if (!saved) return { status: "error" };

  after(() => logAudit("lead.note_added", leadId));
  revalidatePath(`/dashboard/leads/${leadId}`);
  return { status: "ok" };
}

export async function deleteLead(id: string) {
  await authorizeLead(id);
  await db.deleteLead(id);
  revalidatePath("/dashboard");
}

